mapper.select:
SELECT SUM(total_comp_count) AS totalCount, SUM(IFNULL(damaged_comp_count,0) + IFNULL(lost_comp_count,0) + IFNULL(discarded_comp_count,0)) AS abnormalCount, ROUND(SUM(normal_comp_count) / NULLIF(SUM(total_comp_count),0) * 100, 2) AS qualifyRate, ROUND(SUM(update_comp_count) / NULLIF(SUM(IFNULL(damaged_comp_count,0) + IFNULL(lost_comp_count,0)), 0) * 100, 2) AS closeRate, 0 AS yoyGrowth, 0 AS momGrowth FROM stat_mng_comp
AND area_code = #{regionShortCode}
AND stat_cycle = #{statCycle}
